content.text:
{
  "count": 199,
  "tools": [
    {
      "name": "get_account_site_counts",
      "title": "Get Account Site Counts",
      "summary": "Returns the authenticated account identifiers and site count data including current billable sites, maximum allowed sites, and a human-readable usage message. For hybrid plans the response also includes signature and premium tier breakdowns. Use this to check remaining capacity before creating a new site.",
      "category": "accounts"
    },
    {
      "name": "get_site_creation_options",
      "title": "Get Site Creation Options",
      "summary": "Returns the available PHP versions, WordPress versions, install options, and datacenter regions for creating a new site. Call this BEFORE create_site or search_sites to discover valid values for php_version, wordpress_version, install, and datacenter_code parameters.",
      "category": "sites"
    },
    {
      "name": "validate_site_name",
      "title": "Validate Site Name",
      "summary": "Checks whether a proposed site name is valid and available for use. Call this BEFORE create_site to verify the name meets formatting rules and is not already taken. Returns { valid: true } on success or { valid: false, message: \"...\" } explaining the problem.",
      "category": "sites"
    },
    {
      "name": "create_site",
      "title": "Create Site",
      "summary": "Creates a new WordPress site on Pressable. Call get_site_creation_options first to discover valid PHP versions, install options, and datacenter codes, and call validate_site_name to check name availability. Provide a unique site name to generate the WordPress URL (e.g., my-new-site.mystagingwebsite.com). Optionally configure PHP version, datacenter region, custom WordPress admin credentials, and site type (live, staging, or sandbox). The site will initially be in \"deploying\" state and typically becomes \"active\" within 30–60 seconds. After creation, wait at least 30 seconds then call get_site_status to poll until state is \"active\".",
      "category": "sites"
    },
    {
      "name": "get_site_status",
      "title": "Get Site Status",
      "summary": "Retrieves the current status and details of a Pressable WordPress site by its ID.",
      "category": "sites"
    },
    {
      "name": "get_site_details",
      "title": "Get Site Details",
      "summary": "Retrieves comprehensive details of a Pressable WordPress site by its ID.",
      "category": "sites"
    },
    {
      "name": "search_sites",
      "title": "Search Sites",
      "summary": "Search for sites on your Pressable account using one or more filters.",
      "category": "sites"
    },
    {
      "name": "get_site_activity_logs",
      "title": "Get Site Activity Logs",
      "summary": "Retrieves recent activity logs for a Pressable WordPress site.",
      "category": "sites"
    },
    {
      "name": "get_site_activity_actions",
      "title": "Get Site Activity Actions",
      "summary": "Returns all available site activity action names and their descriptions.",
      "category": "sites"
    },
    {
      "name": "get_account_activity_logs",
      "title": "Get Account Activity Logs",
      "summary": "Retrieves recent activity logs for your Pressable account.",
      "category": "accounts"
    },
    {
      "name": "get_account_activity_actions",
      "title": "Get Account Activity Actions",
      "summary": "Returns all available account activity action names and their descriptions.",
      "category": "accounts"
    },
    {
      "name": "update_site_display_name",
      "title": "Update Site Display Name",
      "summary": "Updates the cosmetic display name of a Pressable WordPress site. This changes only the human-friendly label shown in the dashboard — it does not affect the site URL or subdomain.",
      "category": "sites"
    },
    {
      "name": "update_site_php_version",
      "title": "Update Site PHP Version",
      "summary": "Updates the PHP version of a Pressable WordPress site. Valid PHP versions are: 8.3, 8.4, and 8.5. The site must be in a live state.",
      "category": "sites"
    },
    {
      "name": "update_site_wp_environment_type",
      "title": "Update Site WP Environment Type",
      "summary": "Sets the WP_ENVIRONMENT_TYPE constant in the site's wp-config.php file. Valid values are: local, staging, development, and production. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "disable_site",
      "title": "Disable Site",
      "summary": "Disables a live Pressable WordPress site, making it temporarily unavailable. The site must be in a live state. Commonly used for maintenance or incident response. A disabled site remains billable and can be re-enabled with enable_site.",
      "category": "sites"
    },
    {
      "name": "enable_site",
      "title": "Enable Site",
      "summary": "Re-enables a disabled Pressable WordPress site, restoring it to a live state. The site must be in a disabled state. The account's subscription must be active, and the site must not be marked as hacked.",
      "category": "sites"
    },
    {
      "name": "clone_site",
      "title": "Clone Site",
      "summary": "Creates a copy of an existing Pressable WordPress site. The source site's files, database, and configuration are cloned to a new site with the specified name. Call validate_site_name first to check name availability. The cloned site will initially be in \"cloning\" state and typically becomes \"active\" within a few minutes depending on site size. After cloning, use get_site_status to poll until state is \"active\".",
      "category": "sites"
    },
    {
      "name": "convert_site_type",
      "title": "Convert Site Type",
      "summary": "Converts a Pressable WordPress site between live, staging, sandbox, and duplikit types. The site must be in an active state. Certain conversions have additional requirements: converting to live requires the account to have capacity for another live site; converting to staging or sandbox requires no domain records attached; converting to duplikit requires the site to be a sandbox site first. Valid target types are: live, staging, sandbox, duplikit.",
      "category": "sites"
    },
    {
      "name": "list_site_domains",
      "title": "List Site Domains",
      "summary": "Lists all domains attached to a Pressable WordPress site, including the default staging URL (domain_id: -1). Returns site metadata and a domains array where each entry includes id, domain_name, primary status, and health. Use get_domain_details with a specific domain_id for full information including DNS confirmation, provisioning status, zone details, and IP addresses.",
      "category": "sites"
    },
    {
      "name": "get_domain_details",
      "title": "Get Domain Details",
      "summary": "Retrieves detailed information about a specific domain attached to a Pressable WordPress site. Use list_site_domains first to discover domain IDs. The staging URL has a domain_id of -1. Returns the domain name, primary status, health, DNS confirmation, provisioning status, zone information, and associated IP addresses.",
      "category": "sites"
    },
    {
      "name": "add_site_domain",
      "title": "Add Site Domain",
      "summary": "Attaches a domain to a Pressable WordPress site. Provide the full domain name (e.g., \"example.com\" or \"blog.example.com\"). The domain must not already be attached to another account. If this is the site's first custom domain, it is automatically set as primary. Adding a root domain (e.g., \"example.com\") also creates a \"www\" subdomain record automatically. Use list_site_domains to see all domains currently attached to a site.",
      "category": "sites"
    },
    {
      "name": "remove_site_domain",
      "title": "Remove Site Domain",
      "summary": "Removes a domain from a Pressable WordPress site. Requires the domain_id from list_site_domains. The staging URL (domain_id: -1) cannot be removed. If the removed domain was the primary, a new primary is automatically selected. Removing a domain also removes its associated DNS records.",
      "category": "sites"
    },
    {
      "name": "set_primary_domain",
      "title": "Set Primary Domain",
      "summary": "Sets the primary domain for a Pressable WordPress site. Requires the domain_id from list_site_domains. Use domain_id -1 to reset the primary to the default staging URL. The domain must be an A Record and already attached to the site. If any A record on the site is still being provisioned, the request is rejected with the code domains.primary.provisioning_in_progress and can be retried once provisioning finishes. Do not assume the retry window is short: a record that has already failed a step may be on a multi-hour retry ladder, and a stranded record does not retry at all until an operator re-drives it. Provisioning CNAME, TXT or other non-A records do not block the request.",
      "category": "sites"
    },
    {
      "name": "delete_site",
      "title": "Delete Site",
      "summary": "Permanently deletes a Pressable WordPress site. This action is irreversible and removes all site files, database, and configuration. The deletion is blocked when it would destroy a domain that has an active email order — that is, when this site owns every A record on the domain, or the domain has no A records and this site owns some other record on it. Use search_sites or get_site_status to look up the site_id first.",
      "category": "sites"
    },
    {
      "name": "update_site_wordpress_version",
      "title": "Update Site WordPress Version",
      "summary": "Updates the WordPress version track of a Pressable WordPress site. Valid version tracks can be discovered by calling get_site_creation_options. The site must be in a live state.",
      "category": "sites"
    },
    {
      "name": "get_site_edge_cache_status",
      "title": "Get Site Edge Cache Status",
      "summary": "Retrieves the current edge cache status for a Pressable WordPress site. Returns whether edge cache is enabled or disabled, and whether defensive mode is active.",
      "category": "sites"
    },
    {
      "name": "toggle_site_edge_cache",
      "title": "Toggle Site Edge Cache",
      "summary": "Toggles edge cache on or off for a Pressable WordPress site. If edge cache is currently enabled it will be disabled, and vice versa. The site must be in a live state. Use get_site_edge_cache_status to check the current state before toggling.",
      "category": "sites"
    },
    {
      "name": "toggle_site_maintenance_mode",
      "title": "Toggle Site Maintenance Mode",
      "summary": "Toggles maintenance mode on or off for a Pressable WordPress site. When enabled, the site displays a maintenance page to visitors. If maintenance mode is currently enabled it will be disabled, and vice versa. The site must be in a live state. The toggle is processed asynchronously and may take a few moments to complete.",
      "category": "sites"
    },
    {
      "name": "toggle_site_multisite_support",
      "title": "Toggle Site Multisite Support",
      "summary": "Toggles WordPress multisite support on or off for a Pressable site. When enabled, the site supports domain-based WordPress multisite networking. If multisite support is currently enabled it will be disabled, and vice versa. The site must be active and multisite-eligible — via a High Traffic, Hybrid, or Premium plan, or a plan with 5 or more sites.",
      "category": "sites"
    },
    {
      "name": "toggle_site_lightweight_404",
      "title": "Toggle Site Lightweight 404",
      "summary": "Toggles lightweight 404 handling on or off for a Pressable site. When enabled, the site serves a minimal static 404 page instead of loading the full WordPress 404 template, improving performance for missing URLs. If lightweight 404 is currently enabled it will be disabled, and vice versa.",
      "category": "sites"
    },
    {
      "name": "configure_site_basic_auth",
      "title": "Configure Site Basic Authentication",
      "summary": "Configures or removes HTTP basic authentication on a Pressable WordPress site. To enable basic auth, provide site_id, username, and password. To disable basic auth, provide site_id and set disable to true. The site must be in a live state and cannot be a sandbox site. The operation is processed asynchronously and may take a few moments to complete.",
      "category": "sites"
    },
    {
      "name": "set_site_php_filesystem_permissions",
      "title": "Set Site PHP Filesystem Permissions",
      "summary": "Sets the PHP filesystem write permissions for a Pressable WordPress site. Valid permission levels are: \"rw\" (Read/Write — PHP can read and write files), \"ro\" (Read Only — PHP cannot modify files), and \"loggedin\" (Read Only unless logged into WordPress — PHP can write only when a WordPress admin is logged in). The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "get_site_php_logs",
      "title": "Get Site PHP Logs",
      "summary": "Retrieves PHP error logs for a Pressable WordPress site. Returns log entries from the last 7 days, ordered by most recent first.",
      "category": "sites"
    },
    {
      "name": "get_site_webserver_logs",
      "title": "Get Site Webserver Logs",
      "summary": "Retrieves webserver (NGINX) access logs for a Pressable WordPress site. Returns log entries from the last 7 days, ordered by most recent first.",
      "category": "sites"
    },
    {
      "name": "onepress_login",
      "title": "OnePress Login",
      "summary": "Generates a one-time WordPress admin login URL for a Pressable site. The URL expires after 30 seconds and can only be used once. Requires the OnePress Login plugin to be installed on the site. The email must belong to a valid WordPress user on the site.",
      "category": "sites"
    },
    {
      "name": "list_site_ftp_accounts",
      "title": "List Site FTP Accounts",
      "summary": "Lists all SFTP/FTP user accounts for a Pressable WordPress site. Returns site metadata and an ftp_accounts array where each entry includes username, created_at, owner status, and ssh_key_label (the name of the SSH key that login carries, or null when it carries none). Use get_ftp_account_details with a specific username for full information including SFTP domain, home directory, and last accessed time.",
      "category": "sites"
    },
    {
      "name": "get_ftp_account_details",
      "title": "Get FTP Account Details",
      "summary": "Retrieves detailed information about a specific SFTP/FTP user account on a Pressable WordPress site. Use list_site_ftp_accounts first to discover usernames. Returns the username, SFTP domain, home directory, owner status, account email, and timestamps for creation, last access, and last modification.",
      "category": "sites"
    },
    {
      "name": "reset_ftp_password",
      "title": "Reset FTP Password",
      "summary": "Resets the SFTP/FTP password for a specific user account on a Pressable WordPress site. Use list_site_ftp_accounts first to discover usernames. Returns the new plain-text password. The new password is only shown once and cannot be retrieved again.",
      "category": "sites"
    },
    {
      "name": "list_site_collaborators",
      "title": "List Site Collaborators",
      "summary": "Lists all collaborators for a Pressable WordPress site. Returns site metadata and a collaborators array where each entry includes the collaborator ID, email, name, state, and assigned roles. Use get_collaborator_details with a specific collaborator_id for full information including WordPress username and timestamps.",
      "category": "collaborators"
    },
    {
      "name": "get_collaborator_details",
      "title": "Get Collaborator Details",
      "summary": "Retrieves detailed information about a specific collaborator on a Pressable WordPress site. Use list_site_collaborators first to discover collaborator IDs. Returns the collaborator ID, account ID, email, name, state, WordPress username, assigned roles, and timestamps.",
      "category": "collaborators"
    },
    {
      "name": "add_site_collaborator",
      "title": "Add Site Collaborator",
      "summary": "Adds a collaborator to a Pressable WordPress site. Requires the collaborator's email address and optionally accepts a list of role names to assign. Call get_collaborator_roles first to discover valid role names. If the collaborator already exists on the site, their roles are updated to match the provided list. Use list_site_collaborators to verify the result. The caller must have MANAGE_COLLABORATORS permission on the site.",
      "category": "collaborators"
    },
    {
      "name": "remove_site_collaborator",
      "title": "Remove Site Collaborator",
      "summary": "Removes a collaborator from a Pressable WordPress site. Optionally deletes the collaborator's WordPress user as well. The caller must have MANAGE_COLLABORATORS permission, or be the site owner, or be removing themselves. Use list_site_collaborators first to discover collaborator IDs.",
      "category": "collaborators"
    },
    {
      "name": "reset_collaborator_wp_password",
      "title": "Reset Collaborator WordPress Password",
      "summary": "Resets the WordPress admin password for a collaborator on a Pressable WordPress site. Generates a random password and returns it in plain text (shown only once). The caller must be the site owner or the collaborator resetting their own password. The collaborator must have WP_ACCESS. Use list_site_collaborators first to discover collaborator IDs.",
      "category": "collaborators"
    },
    {
      "name": "get_collaborator_roles",
      "title": "Get Collaborator Roles",
      "summary": "Returns the list of available site-level roles that can be assigned when adding or updating a collaborator. Call this BEFORE add_site_collaborator to discover valid role names. Note: if all of add_to_all_new, create_site, manage_tags, manage_sso, account_notifications, site_management_notifications, site_operation_notifications, account_administrator, view_usage, manage_billing, manage_email and delegate_email_notification_capabilities are set to false, the collaborator loses every account-level capability these settings control on the API application owner's account but remains attached to any sites where they were previously added.",
      "category": "collaborators"
    },
    {
      "name": "list_account_collaborators",
      "title": "List Account Collaborators",
      "summary": "Lists all collaborators across your Pressable account. Returns every collaborator record including their email, name, state, site, roles, and WordPress username. A person who collaborates on multiple sites will appear once per site. Use get_account_collaborator_details with a collaborator_id for full details on one record.",
      "category": "collaborators"
    },
    {
      "name": "get_account_collaborator_details",
      "title": "Get Account Collaborator Details",
      "summary": "Retrieves detailed information about a specific collaborator on your Pressable account. Use list_account_collaborators first to discover collaborator IDs. Returns the collaborator's ID, email, name, state, WordPress username, site, roles, and timestamps.",
      "category": "collaborators"
    },
    {
      "name": "get_account_collaborator_sites",
      "title": "Get Account Collaborator Sites",
      "summary": "Lists all sites a specific collaborator has access to within your Pressable account. Returns each site's ID, name, state, roles, and WordPress username. Use list_account_collaborators first to discover collaborator emails.",
      "category": "collaborators"
    },
    {
      "name": "update_collaborator_access",
      "title": "Update Collaborator Access",
      "summary": "Updates account-level collaborator access permissions. Provide the collaborator's email and the capabilities to change. If the collaborator does not yet have an account, an invitation is sent automatically. Every capability flag follows the same rule: true grants it, false revokes it, and omitting it leaves the current setting unchanged, so send only the flags you want to change. Setting every flag to false revokes every account-level capability this tool controls (but does not remove the collaborator from individual sites). The roles parameter specifies which site roles are automatically assigned to new sites, and is applied only when add_to_all_new is true: send roles whenever add_to_all_new is true, or the new-site default roles are cleared. Call get_collaborator_roles to discover valid role names. The response's top-level flags are the stored grants; effective_capabilities is a read-only map of the same keys showing what the collaborator can actually do (an Account Administrator holds every capability it implies), and is ignored if sent.",
      "category": "collaborators"
    },
    {
      "name": "batch_create_collaborators",
      "title": "Batch Create Collaborators",
      "summary": "Adds a collaborator to multiple sites in a single batch operation. Provide the collaborator's email address and an array of site IDs. Use [-1] as the site_ids value to add the collaborator to all your live sites. Only live sites where you have MANAGE_COLLABORATORS permission are included. The operation runs asynchronously in the background. Call get_collaborator_roles to discover valid role names.",
      "category": "collaborators"
    },
    {
      "name": "batch_remove_collaborators",
      "title": "Batch Remove Collaborators",
      "summary": "Removes a collaborator from multiple sites in a single batch operation. Provide the collaborator's email address and an array of site IDs. Use [-1] as the site_ids value to remove the collaborator from all your live sites. Only live sites where you have MANAGE_COLLABORATORS permission are included. Optionally delete the collaborator's WordPress user on each site. The operation runs asynchronously in the background.",
      "category": "collaborators"
    },
    {
      "name": "list_wordpress_users",
      "title": "List WordPress Users",
      "summary": "Lists WordPress users on a Pressable site. Returns user details including ID, login, display name, email, and roles. Supports pagination via page and per_page parameters. The site must be in an active state. Maximum 200 users per page.",
      "category": "sites"
    },
    {
      "name": "create_wordpress_user",
      "title": "Create WordPress User",
      "summary": "Creates a new WordPress user on a Pressable site. Provide the email address for the new user, and optionally a role (administrator, editor, author, contributor, or subscriber); the role defaults to administrator when omitted. A random password is generated automatically and returned in the response (shown only once). The email is also used as the WordPress username. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "list_site_plugins",
      "title": "List Site Plugins",
      "summary": "Lists all installed WordPress plugins on a Pressable site including active, inactive, drop-in, and must-use plugins. Returns each plugin's name, title, status, version, and update availability. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "get_site_plugin_security_alerts",
      "title": "Get Site Plugin Security Alerts",
      "summary": "Retrieves plugins with known security vulnerabilities installed on a Pressable WordPress site. Returns each vulnerable plugin's name, version, status, and a list of associated vulnerabilities including severity, title, description, fix version, and published date. Only plugins with at least one known vulnerability are included. Requires MANAGE_WORDPRESS permission.",
      "category": "sites"
    },
    {
      "name": "install_site_plugins",
      "title": "Install Site Plugins",
      "summary": "Installs and activates WordPress plugins on a Pressable site. Each plugin requires a path (plugin slug from the WordPress.org directory, or a URL to a plugin ZIP file). Optionally specify a version to install a specific release. The operation runs asynchronously in the background. Use list_site_plugins to verify the result. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "update_site_plugins",
      "title": "Update Site Plugins",
      "summary": "Updates WordPress plugins on a Pressable site. Each plugin requires a path (plugin slug). Optionally specify a version to update to a specific release; omit for the latest version. The operation runs asynchronously in the background. Use list_site_plugins to verify the result. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "activate_site_plugins",
      "title": "Activate Site Plugins",
      "summary": "Activates installed WordPress plugins on a Pressable site. Each plugin requires a path (plugin slug). The plugin must already be installed on the site. The operation runs asynchronously in the background. Use list_site_plugins to verify the result. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "deactivate_site_plugins",
      "title": "Deactivate Site Plugins",
      "summary": "Deactivates active WordPress plugins on a Pressable site. Each plugin requires a path (plugin slug). The plugin must currently be active on the site. The operation runs asynchronously in the background. Use list_site_plugins to verify the result. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "delete_site_plugins",
      "title": "Delete Site Plugins",
      "summary": "Deletes (removes) WordPress plugins from a Pressable site. Each plugin requires a path (plugin slug, not a URL). Plugins should be deactivated before deletion. The operation runs asynchronously in the background. Use list_site_plugins to verify the result. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "list_site_themes",
      "title": "List Site Themes",
      "summary": "Lists all installed WordPress themes on a Pressable site including active and inactive themes. Returns each theme's name, title, status, version, and update availability. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "get_site_theme_security_alerts",
      "title": "Get Site Theme Security Alerts",
      "summary": "Retrieves themes with known security vulnerabilities installed on a Pressable WordPress site. Returns each vulnerable theme's name, version, status, and a list of associated vulnerabilities including severity, title, description, fix version, published date, and reference URLs. Only themes with at least one known vulnerability are included. Requires MANAGE_WORDPRESS permission.",
      "category": "sites"
    },
    {
      "name": "install_site_themes",
      "title": "Install Site Themes",
      "summary": "Installs and activates WordPress themes on a Pressable site. Each theme requires a path (theme slug from the WordPress.org directory, or a URL to a theme ZIP file). Optionally specify a version to install a specific release. The operation runs asynchronously in the background. Use list_site_themes to verify the result. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "update_site_themes",
      "title": "Update Site Themes",
      "summary": "Updates WordPress themes on a Pressable site. Each theme requires a path (theme slug). Optionally specify a version to update to a specific release; omit for the latest version. The operation runs asynchronously in the background. Use list_site_themes to verify the result. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "activate_site_themes",
      "title": "Activate Site Themes",
      "summary": "Activates installed WordPress themes on a Pressable site. Each theme requires a path (theme slug). The theme must already be installed on the site. The operation runs asynchronously in the background. Use list_site_themes to verify the result. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "delete_site_themes",
      "title": "Delete Site Themes",
      "summary": "Deletes (removes) WordPress themes from a Pressable site. Each theme requires a path (theme slug, not a URL). The operation runs asynchronously in the background. Use list_site_themes to verify the result. The site must be in an active state.",
      "category": "sites"
    },
    {
      "name": "list_site_backups",
      "title": "List Site Backups",
      "summary": "Lists scheduled filesystem and database backups for a Pressable WordPress site. Returns each backup point's date, time, and the associated filesystem and database backup IDs. Backups are ordered by most recent first.",
      "category": "sites"
    },
    {
      "name": "get_site_backup_details",
      "title": "Get Site Backup Details",
      "summary": "Retrieves details for a specific filesystem or database backup on a Pressable WordPress site. Returns the backup's type (filesystem or database), date, time, and identifiers. Use list_site_backups to discover available backup IDs.",
      "category": "sites"
    },
    {
      "name": "restore_site_backup",
      "title": "Restore Site Backup",
      "summary": "Initiates a restore of a Pressable WordPress site from a filesystem and/or database backup. At least one of filesystem_id or database_id must be provided. There are two modes: omit restore_on_site_id to restore site_id's backup back onto site_id itself, or pass restore_on_site_id to run a cross-site restore, where site_id supplies the backup and restore_on_site_id is the site that gets overwritten. Sites must be in a live state and must not exceed the maximum restorable size; a cross-site restore additionally requires both sites to belong to the same account and to be two different sites. Use list_site_backups to discover available backup IDs. The restore runs asynchronously in the background. Poll get_site_restore_status (or list_site_restores) for its progress and outcome.",
      "category": "sites"
    },
    {
      "name": "list_site_ondemand_backups",
      "title": "List On-Demand Backups",
      "summary": "Lists active on-demand backups for a Pressable WordPress site. Returns each backup's ID, type (filesystem or database), status, size, creation date, and expiration info. Only customer-created backups are included. Backups are ordered by most recent first.",
      "category": "sites"
    },
    {
      "name": "create_site_ondemand_backup",
      "title": "Create On-Demand Backup",
      "summary": "Creates a new on-demand filesystem or database backup for a Pressable WordPress site. Each site can have up to 3 customer-created filesystem backups and 3 database backups. The backup is created asynchronously and may take several minutes to complete. Use list_site_ondemand_backups to check status.",
      "category": "sites"
    },
    {
      "name": "get_site_ondemand_backup_details",
      "title": "Get On-Demand Backup Details",
      "summary": "Retrieves details for a specific on-demand backup on a Pressable WordPress site. Returns the backup's ID, type, status, size, creation date, completion date, creator, and expiration info. Use list_site_ondemand_backups to discover available backup IDs.",
      "category": "sites"
    },
    {
      "name": "delete_site_ondemand_backup",
      "title": "Delete On-Demand Backup",
      "summary": "Deletes an on-demand backup from a Pressable WordPress site. The deletion is processed asynchronously in the background. Use list_site_ondemand_backups to discover available backup IDs.",
      "category": "sites"
    },
    {
      "name": "download_site_ondemand_backup",
      "title": "Download On-Demand Backup",
      "summary": "Generates download information for an on-demand backup on a Pressable WordPress site. Returns the backup metadata, filename, and the API download URL. The download URL requires authentication with the Pressable API. Use list_site_ondemand_backups to discover available backup IDs.",
      "category": "sites"
    },
    {
      "name": "get_site_statistics",
      "title": "Get Site Statistics",
      "summary": "Retrieves storage usage and page view statistics for a Pressable WordPress site.",
      "category": "sites"
    },
    {
      "name": "get_site_performance_report",
      "title": "Get Site Performance Report",
      "summary": "Retrieves the latest Lighthouse performance report for a Pressable WordPress site.",
      "category": "sites"
    },
    {
      "name": "get_site_usage_report",
      "title": "Get Site Usage Report",
      "summary": "Retrieves billing-cycle usage data for a Pressable WordPress site.",
      "category": "sites"
    },
    {
      "name": "get_site_metrics",
      "title": "Get Site Metrics",
      "summary": "Retrieves real-time performance metrics for a Pressable WordPress site from WP Cloud.",
      "category": "sites"
    },
    {
      "name": "list_site_firewall_rules",
      "title": "List Site Firewall Rules",
      "summary": "Lists all egress firewall rules for a Pressable WordPress site. Returns site metadata and a firewall_rules array where each entry includes id, destination, port, protocol, and created_at. Use get_firewall_rule_details with a specific firewall_rule_id for full information including the account that created the rule and timestamps.",
      "category": "sites"
    },
    {
      "name": "get_firewall_rule_details",
      "title": "Get Firewall Rule Details",
      "summary": "Retrieves detailed information about a specific egress firewall rule on a Pressable WordPress site. Use list_site_firewall_rules first to discover firewall rule IDs. Returns the destination IP/CIDR, port, protocol, the account that created the rule, and full timestamps.",
      "category": "sites"
    },
    {
      "name": "create_site_firewall_rule",
      "title": "Create Site Firewall Rule",
      "summary": "Creates a new egress firewall rule on a Pressable WordPress site. Requires a destination IP address or CIDR block, a port number (1-65535), and a protocol (tcp or udp). The site must be active. Duplicate rules (same destination, port, and protocol) are not allowed. Use list_site_firewall_rules to see existing rules before creating a new one.",
      "category": "sites"
    },
    {
      "name": "delete_site_firewall_rule",
      "title": "Delete Site Firewall Rule",
      "summary": "Deletes an egress firewall rule from a Pressable WordPress site. Use list_site_firewall_rules first to discover firewall rule IDs. This action is irreversible — the rule will be removed from both the Pressable platform and the underlying infrastructure.",
      "category": "sites"
    },
    {
      "name": "refresh_site_firewall_rules",
      "title": "Refresh Site Firewall Rules",
      "summary": "Schedules a refresh of all egress firewall rules for a Pressable WordPress site. This re-syncs the local firewall rule records with the underlying infrastructure. The refresh runs asynchronously and may take a few seconds to complete. Use list_site_firewall_rules afterwards to see the updated rules.",
      "category": "sites"
    },
    {
      "name": "list_site_cron_jobs",
      "title": "List Site Cron Jobs",
      "summary": "Lists all scheduled cron jobs for a Pressable WordPress site. Returns site metadata and a cron_jobs array where each entry includes cron_id, schedule, requested_schedule, and command. requested_schedule is the friendly shorthand from the original request (e.g. \"2h\") and schedule is the generated cron expression aligned to it; it may be null for jobs created before requested_schedule was introduced. Use create_site_cron_job to add a new cron job or delete_site_cron_job to remove one.",
      "category": "sites"
    },
    {
      "name": "create_site_cron_job",
      "title": "Create Site Cron Job",
      "summary": "Creates a new scheduled cron job on a Pressable WordPress site. Requires a schedule interval (1h, 1d, 2d, or 1w) and a command to execute. The site must have a valid cloud ID. Use list_site_cron_jobs to see existing cron jobs before creating a new one.",
      "category": "sites"
    },
    {
      "name": "delete_site_cron_job",
      "title": "Delete Site Cron Job",
      "summary": "Deletes a scheduled cron job from a Pressable WordPress site. Use list_site_cron_jobs first to discover cron job IDs. This action is irreversible — the cron job will be permanently removed from the site.",
      "category": "sites"
    },
    {
      "name": "list_dns_zones",
      "title": "List DNS Zones",
      "summary": "Lists all DNS zones for the authenticated account. Returns zone metadata including id, name, and creation date. Use list_dns_zone_records with a specific zone_id to see the DNS records within a zone.",
      "category": "accounts"
    },
    {
      "name": "list_dns_zone_records",
      "title": "List DNS Zone Records",
      "summary": "Lists all DNS records for a specific zone. Returns zone metadata and a records array where each entry includes id, type, name, value, ttl, priority, weight, port, and primary status. Use get_dns_record_details for full information about a specific record. Use list_dns_zones first to discover zone IDs.",
      "category": "accounts"
    },
    {
      "name": "get_dns_record_details",
      "title": "Get DNS Record Details",
      "summary": "Retrieves detailed information about a specific DNS record within a zone. Returns the full record including id, type, name, value, ttl, priority, weight, port, primary status, site_id (for A records), and timestamps. Use list_dns_zone_records first to discover record IDs.",
      "category": "accounts"
    },
    {
      "name": "create_dns_record",
      "title": "Create DNS Record",
      "summary": "Creates a DNS record in a specific zone. Supports record types: A, AAAA, CNAME, MX, PTR, SRV, and TXT. A and AAAA records require a site_id. MX records accept a priority. SRV records accept priority, weight, and port. The TTL defaults to 3600 if not specified. Use list_dns_zones to discover zone IDs and search_sites to find site IDs for A/AAAA records. Use list_dns_zone_records to see existing records before creating a new one.",
      "category": "accounts"
    },
    {
      "name": "update_dns_record",
      "title": "Update DNS Record",
      "summary": "Updates a DNS record by replacing it with new values. Internally deletes the original record and then creates a new one; the two steps are not atomic, so if the create fails the original record stays deleted rather than being restored. Requires the record_id of the existing record and the full set of new values (type and value are required; name, ttl, site_id, priority, weight, and port are optional). A and AAAA records require a site_id. Use list_dns_zone_records to discover record IDs before updating. If the original record is the primary A record, a new primary is automatically selected during the replacement.",
      "category": "accounts"
    },
    {
      "name": "delete_dns_record",
      "title": "Delete DNS Record",
      "summary": "Deletes a DNS record from a specific zone. This action is irreversible. The record and any associated DNS provider entries are removed. If the deleted record is the primary A record, a new primary is automatically selected. The deletion is blocked if it would destroy a zone that has an active or pending email order — either because it removes the zone's last A record, or because the zone has no A records at all, in which case removing any record destroys it. Use list_dns_zone_records to discover record IDs before deleting.",
      "category": "accounts"
    },
    {
      "name": "add_site_tags",
      "title": "Add Site Tags",
      "summary": "Adds one or more organizational tags to a Pressable WordPress site. Each tag entry requires either a name (to create or reuse a tag) or a tag_id (to use an existing tag), but not both. Optionally specify a color for new tags (e.g., \"gray\", \"blue\", \"red\"). Tags are useful for organizing and filtering sites. The caller must have manage_tags permission on the site's account.",
      "category": "sites"
    },
    {
      "name": "remove_site_tags",
      "title": "Remove Site Tags",
      "summary": "Removes one or more tags from a Pressable WordPress site by tag ID. Use search_sites or get_site_details to discover tag IDs currently assigned to a site. The caller must have manage_tags permission on the site's account.",
      "category": "sites"
    },
    {
      "name": "list_site_notes",
      "title": "List Site Notes",
      "summary": "Lists all customer notes for a Pressable WordPress site. Returns site metadata and a notes array where each entry includes id, subject, body, author email, editor email, and timestamps. Use create_site_note to add a new note or get_site_note_details with a specific note ID for full information.",
      "category": "sites"
    },
    {
      "name": "get_site_note_details",
      "title": "Get Site Note Details",
      "summary": "Retrieves detailed information about a specific customer note on a Pressable WordPress site. Returns the full note including id, subject, body, author email, editor email, and timestamps. Use list_site_notes first to discover note IDs.",
      "category": "sites"
    },
    {
      "name": "create_site_note",
      "title": "Create Site Note",
      "summary": "Creates a new customer note on a Pressable WordPress site. Notes are useful for recording context, decisions, or instructions about a site. Both subject and body are required. Emojis are automatically stripped from the subject and body. Use list_site_notes to see existing notes.",
      "category": "sites"
    },
    {
      "name": "update_site_note",
      "title": "Update Site Note",
      "summary": "Updates an existing customer note on a Pressable WordPress site. Both subject and body are required and will replace the current values. Emojis are automatically stripped. Use list_site_notes first to discover note IDs.",
      "category": "sites"
    },
    {
      "name": "delete_site_note",
      "title": "Delete Site Note",
      "summary": "Deletes a customer note from a Pressable WordPress site. This action is irreversible. Use list_site_notes first to discover note IDs.",
      "category": "sites"
    },
    {
      "name": "set_site_filesystem_usage_limit",
      "title": "Set Site Filesystem Usage Limit",
      "summary": "Sets the filesystem storage usage limit and warning threshold for a Pressable WordPress site. When usage approaches the limit (within warning_headroom bytes), a warning alert is triggered. When usage exceeds the limit, an over-limit alert is triggered. Setting limit to 0 or omitting it removes the limit entirely. The warning_headroom must be less than or equal to the limit — if it exceeds the limit, it is automatically reset to 0. Use get_site_details to view current limits. The caller must have manage_performance permission on the site.",
      "category": "sites"
    },
    {
      "name": "set_site_database_usage_limit",
      "title": "Set Site Database Usage Limit",
      "summary": "Sets the database storage usage limit and warning threshold for a Pressable WordPress site. When usage approaches the limit (within warning_headroom bytes), a warning alert is triggered. When usage exceeds the limit, an over-limit alert is triggered. Setting limit to 0 or omitting it removes the limit entirely. The warning_headroom must be less than or equal to the limit — if it exceeds the limit, it is automatically reset to 0. Use get_site_details to view current limits. The caller must have manage_performance permission on the site.",
      "category": "sites"
    },
    {
      "name": "activate_site_apm",
      "title": "Activate Site APM",
      "summary": "Activates Application Performance Monitoring (APM) trace capture for a Pressable WordPress site. APM traces help diagnose slow requests and performance regressions.",
      "category": "sites"
    },
    {
      "name": "deactivate_site_apm",
      "title": "Deactivate Site APM",
      "summary": "Deactivates Application Performance Monitoring (APM) trace capture for a Pressable WordPress site. APM must currently be active for this to succeed. Previously captured traces remain accessible via get_site_apm_url.",
      "category": "sites"
    },
    {
      "name": "get_site_apm_url",
      "title": "Get Site APM URL",
      "summary": "Retrieves a temporary URL for the Application Performance Monitoring (APM) trace viewer dashboard. APM does not need to be currently active to access previously captured traces, but at least one trace capture window must have existed for the URL to be useful.",
      "category": "sites"
    },
    {
      "name": "get_site_jetpack_status",
      "title": "Get Site Jetpack Status",
      "summary": "Retrieves the current Jetpack connection and licensing status for a Pressable WordPress site.",
      "category": "sites"
    },
    {
      "name": "connect_site_jetpack",
      "title": "Connect Site Jetpack",
      "summary": "Requests Jetpack to be (re)connected for a Pressable WordPress site. This enqueues a job that sets the site's active Jetpack license key on the site via SSH/WP-CLI, which restores the Jetpack connection if it was misconfigured or lost.",
      "category": "sites"
    },
    {
      "name": "list_account_mu_plugins",
      "title": "List Account Must-Use Plugins",
      "summary": "Lists all must-use (mu) plugins registered on your Pressable account. Must-use plugins are auto-loaded by WordPress on every site and cannot be deactivated from the WP admin. Each plugin record tracks whether it is applied to existing sites and/or future sites.",
      "category": "accounts"
    },
    {
      "name": "get_account_mu_plugin_details",
      "title": "Get Account Must-Use Plugin Details",
      "summary": "Retrieves detailed information about a specific must-use (mu) plugin on your Pressable account. Use list_account_mu_plugins first to discover plugin ids. Returns the plugin's id, slug, path, existing_sites flag, future_sites flag, and timestamps.",
      "category": "accounts"
    },
    {
      "name": "create_account_mu_plugin",
      "title": "Create Account Must-Use Plugin",
      "summary": "Registers a new must-use (mu) plugin on your Pressable account. Must-use plugins are auto-loaded by WordPress on every site and cannot be deactivated from the WP admin.",
      "category": "accounts"
    },
    {
      "name": "update_account_mu_plugin",
      "title": "Update Account Must-Use Plugin",
      "summary": "Re-downloads and updates an existing must-use (mu) plugin across all sites on your Pressable account. This pulls a fresh copy of the PHP file from the registered path and deploys it to every site.",
      "category": "accounts"
    },
    {
      "name": "delete_account_mu_plugin",
      "title": "Delete Account Must-Use Plugin",
      "summary": "Deletes a must-use (mu) plugin from your Pressable account and removes it from all sites. The deletion is performed asynchronously — a background job removes the plugin file from every active site, then destroys the plugin record.",
      "category": "accounts"
    },
    {
      "name": "list_bash_command_bookmarks",
      "title": "List Bash Command Bookmarks",
      "summary": "Lists all saved bash/WP-CLI command bookmarks on your Pressable account. Bookmarks are reusable command shortcuts that can be executed across sites.",
      "category": "accounts"
    },
    {
      "name": "get_bash_command_bookmark",
      "title": "Get Bash Command Bookmark",
      "summary": "Retrieves detailed information about a specific bash/WP-CLI command bookmark by its ID. The bookmark must belong to your account.",
      "category": "accounts"
    },
    {
      "name": "create_bash_command_bookmark",
      "title": "Create Bash Command Bookmark",
      "summary": "Creates a new bash/WP-CLI command bookmark on your Pressable account. Bookmarks are reusable command shortcuts that can be executed across sites.",
      "category": "accounts"
    },
    {
      "name": "update_bash_command_bookmark",
      "title": "Update Bash Command Bookmark",
      "summary": "Updates an existing bash/WP-CLI command bookmark on your Pressable account. All fields (name, command, command_type, description) must be provided. The bookmark name must remain unique within the account. Commands containing dangerous patterns are rejected.",
      "category": "accounts"
    },
    {
      "name": "delete_bash_command_bookmark",
      "title": "Delete Bash Command Bookmark",
      "summary": "Permanently deletes a bash/WP-CLI command bookmark from your Pressable account. This action is irreversible. Bookmarks that are currently in use by a bulk operation cannot be deleted.",
      "category": "accounts"
    },
    {
      "name": "update_account_default_php_version",
      "title": "Update Account Default PHP Version",
      "summary": "Sets the account-level default PHP version that will be applied to every new site created on this Pressable account. Existing sites are not affected by this change — use update_site_php_version to change the PHP version on an individual site.",
      "category": "accounts"
    },
    {
      "name": "run_site_wpcli_commands",
      "title": "Run Site WP-CLI Commands",
      "summary": "Schedules one or more WP-CLI commands to run on a Pressable WordPress site. Each command runs asynchronously on the site's SSH host; the tool returns a list of background job ids that correspond to each queued command.",
      "category": "sites"
    },
    {
      "name": "run_site_bash_commands",
      "title": "Run Site Bash Commands",
      "summary": "Schedules one or more raw bash/shell commands to run on a Pressable WordPress site. Each command runs asynchronously on the site's SSH host; the tool returns a list of background job ids that correspond to each queued command.",
      "category": "sites"
    },
    {
      "name": "batch_execute_bash_command",
      "title": "Batch Execute Bash Command",
      "summary": "Schedules a bash or WP-CLI command to run on multiple Pressable sites in a single bulk operation. Scoped by EXECUTE_BULK_OPERATIONS access: the command only runs on sites the authenticated user owns or collaborates on with that role, and only on sites in the \"live\" state.",
      "category": "accounts"
    },
    {
      "name": "add_site_favorite",
      "title": "Add Site Favorite",
      "summary": "Marks a Pressable WordPress site as a favorite for the authenticated account. Favorited sites are surfaced first in search_sites results.",
      "category": "sites"
    },
    {
      "name": "remove_site_favorite",
      "title": "Remove Site Favorite",
      "summary": "Removes the favorite mark from a Pressable WordPress site for the authenticated account. After removal, the site no longer appears at the top of search_sites results.",
      "category": "sites"
    },
    {
      "name": "list_site_favorites",
      "title": "List Site Favorites",
      "summary": "Lists the Pressable WordPress sites the authenticated account has marked as favorites. Use add_site_favorite and remove_site_favorite to manage favorites.",
      "category": "sites"
    },
    {
      "name": "purge_site_edge_cache",
      "title": "Purge Site Edge Cache",
      "summary": "Purges (clears) the edge cache for a Pressable WordPress site. Use this after content updates to force visitors to receive the latest version of the site instead of cached responses.",
      "category": "sites"
    },
    {
      "name": "toggle_site_edge_cache_defensive_mode",
      "title": "Toggle Site Edge Cache Defensive Mode",
      "summary": "Enables or disables edge cache defensive mode for a Pressable WordPress site. Defensive mode is a temporary mitigation that aggressively caches at the edge to absorb traffic spikes or attacks.",
      "category": "sites"
    },
    {
      "name": "flush_site_object_cache",
      "title": "Flush Site Object Cache",
      "summary": "Flushes the WordPress object cache for a Pressable WordPress site. Useful after data updates that bypass the WordPress write path (direct database writes, restored backups, certain admin tasks).",
      "category": "sites"
    },
    {
      "name": "purge_site_cdn_cache",
      "title": "Purge Site CDN Cache",
      "summary": "Purges (clears) the Content Delivery Network (CDN) cache for a Pressable WordPress site. Use this after content updates to force the CDN edge nodes to fetch the latest version of the site instead of serving cached responses.",
      "category": "sites"
    },
    {
      "name": "reset_site_wordpress_owner_password",
      "title": "Reset Site WordPress Owner Password",
      "summary": "Resets the site owner's WordPress admin password for a Pressable WordPress site. A random password is always generated; it cannot be supplied. The new password is returned in plain text and is shown only once.",
      "category": "sites"
    },
    {
      "name": "reset_site_wordpress_user_password",
      "title": "Reset Site WordPress User Password",
      "summary": "Resets a WordPress user's password on a Pressable WordPress site. Identify the user by numeric ID, email, or login name. A new password can be supplied; if omitted, a random password is generated. The final password (supplied or generated) is returned in plain text and is shown only once.",
      "category": "sites"
    },
    {
      "name": "get_site_phpmyadmin_url",
      "title": "Get Site phpMyAdmin URL",
      "summary": "Retrieves a phpMyAdmin login URL for a Pressable WordPress site. The URL grants temporary database administration access — treat it like a credential and share it carefully. Each call generates a new login URL.",
      "category": "sites"
    },
    {
      "name": "list_site_filesystem_backups",
      "title": "List Site Filesystem Backups",
      "summary": "Lists filesystem backups for a Pressable WordPress site, including both scheduled and on-demand backups. Returns each backup's id, backup_timestamp, type, title, and formatted_timestamp. Backups are ordered by most recent first. Use list_site_database_backups for database backups, or list_site_backups for paired filesystem and database backups.",
      "category": "sites"
    },
    {
      "name": "list_site_database_backups",
      "title": "List Site Database Backups",
      "summary": "Lists database backups for a Pressable WordPress site, including both scheduled and on-demand backups. Returns each backup's id, backup_timestamp, type, title, and formatted_timestamp. Backups are ordered by most recent first. Use list_site_filesystem_backups for filesystem backups, or list_site_backups for paired filesystem and database backups.",
      "category": "sites"
    },
    {
      "name": "download_site_backup",
      "title": "Download Site Backup",
      "summary": "Generates download information for a scheduled backup on a Pressable WordPress site. Returns the backup metadata, filename, and the API download URL. The download URL requires authentication with the Pressable API. Use list_site_backups, list_site_filesystem_backups, or list_site_database_backups to discover available backup IDs.",
      "category": "sites"
    },
    {
      "name": "get_dns_zone_record_ssl_status",
      "title": "Get DNS Zone Record SSL Status",
      "summary": "Retrieves SSL certificate provisioning info for a DNS A record. Returns zone/record metadata plus an ssl payload containing force_ssl, acme_certificate_id, validation_expiration, authz_uri, options, certificate_expiration_date, broken_record, and broken_check. SSL info is only available for A records. Use list_dns_zone_records to discover record IDs. If SSL provisioning is broken (broken_check is populated), use retry_dns_zone_record_ssl to re-attempt provisioning after fixing DNS validation issues.",
      "category": "accounts"
    },
    {
      "name": "retry_dns_zone_record_ssl",
      "title": "Retry DNS Zone Record SSL",
      "summary": "Re-triggers SSL certificate provisioning for a DNS A record. Use after resolving DNS validation issues surfaced by get_dns_zone_record_ssl_status. The retry runs asynchronously and also queues retries for every sibling A record attached to the same site, so a single call re-provisions SSL for the entire site. SSL retry only works on A records. Use list_dns_zone_records to discover record IDs.",
      "category": "accounts"
    },
    {
      "name": "refresh_site_plugins",
      "title": "Refresh Site Plugins",
      "summary": "Re-syncs the stored plugin list for a Pressable WordPress site by querying the live WordPress install. The refresh runs asynchronously via a background job; this tool returns the initial operation status, job_type, and log_messages. Use list_site_plugins afterwards to read the refreshed plugin list. The site must be in an active state. Only one plugin operation can be in progress per site at a time.",
      "category": "sites"
    },
    {
      "name": "refresh_site_themes",
      "title": "Refresh Site Themes",
      "summary": "Re-syncs the stored theme list for a Pressable WordPress site by querying the live WordPress install. The refresh runs asynchronously via a background job; this tool returns the initial operation status, job_type, and log_messages. Use list_site_themes afterwards to read the refreshed theme list. The site must be in an active state. Only one theme operation can be in progress per site at a time.",
      "category": "sites"
    },
    {
      "name": "sync_sites",
      "title": "Sync Sites",
      "summary": "Syncs filesystem and/or database data from one Pressable site (source) to another (destination) via the on-demand backup system. Both sites must belong to the same Pressable account, both must be in the live state, and the account must have the manage_backups_restores permission on both. The sync runs asynchronously: on-demand backups are generated for the source and destination, then the sync proceeds. Use the high-level sync param ('filesystem', 'database', or 'both') for a quick scope, OR omit sync and pass granular boolean flags (filesystem, database, themes_directory, plugins_directory, uploads_directory, wp_content_directory, root_directory) for fine-grained control over which directories to copy. The destination's filesystem and database are overwritten by the source's content for the selected scope.",
      "category": "sites"
    },
    {
      "name": "disconnect_site_ssh",
      "title": "Disconnect Site SSH Sessions",
      "summary": "Forcibly disconnects all active SSH sessions on a Pressable WordPress site. Useful for incident response, kicking off stuck or unauthorized SSH connections, or before rotating SFTP credentials.",
      "category": "sites"
    },
    {
      "name": "update_account_default_datacenter",
      "title": "Update Account Default Datacenter",
      "summary": "Sets the account-level default datacenter that will be applied to every new site created on this Pressable account. Existing sites are not affected by this change — datacenter placement on an existing site is set at creation time and is not changeable here.",
      "category": "accounts"
    },
    {
      "name": "list_account_addons",
      "title": "List Account Addons",
      "summary": "Lists the self-service addons available to be attached to the authenticated Pressable account. The catalog is scoped to the account's current subscription product family — accounts on a different plan family see a different catalog.",
      "category": "accounts"
    },
    {
      "name": "get_attached_account_addons",
      "title": "Get Attached Account Addons",
      "summary": "Returns the addons currently attached to the authenticated Pressable account's subscription. Includes only addons with a non-zero allocation that are visible to the customer — self-service addons, bundled addons, and addons from the Automattic partner program family.",
      "category": "accounts"
    },
    {
      "name": "update_attached_account_addons",
      "title": "Update Attached Account Addons",
      "summary": "Updates the allocation quantity of a single addon on the authenticated Pressable account's subscription. Setting the quantity to 0 detaches the addon. The change is applied via the billing provider (Chargify) and is reflected in the next invoice cycle.",
      "category": "accounts"
    },
